input.command:
cd /private/var/folders/tb/68tnh0pn5619ks87wpp1gqmc0000gp/T/ng-facts-atlas-blast-tool-v2-0KwYkK/workspace; for s in app-tent app-ration app-helmet; do node ../tools/ng-facts.mjs where $s --root . | grep '^Routes that' -A0 | sed 's/^[^:]*: //' > /dev/null; done
node -e '
const {execSync}=require("child_process");
const f=s=>execSync(`node ../tools/ng-facts.mjs where ${s} --root .`).toString().split("\n").find(l=>l.startsWith("Routes that")).replace(/^[^:]*: /,"").split(", ");
const u=execSync("node ../tools/ng-facts.mjs unrouted --root .").toString().split("\n").slice(1).map(l=>l.trim().split(/\s+/)[0]).filter(Boolean);
require("fs").writeFileSync("answers.json",JSON.stringify({tentRoutes:f("app-tent"),rationRoutes:f("app-ration"),helmetRoutes:f("app-helmet"),unroutedComponents:u},null,1));
'; cat answers.json | head -c 600; grep -c . answers.json

